using System;using System.IO;using System.Linq;using System.Collections.Generic;using Por.Core;
class Host:IGameIoHost{public List<string> Events;public bool KeyPressed{get{return false;}}public byte ReadKey(){Events.Add("key");return 13;}public void SoundCommand(ushort c){throw new Exception();}public void SoundSuspend(){throw new Exception();}public void Interrupt(byte n,Types.TInterruptRegisters r){throw new Exception();}public void Halt(int c){throw new Exception();}public void WriteLine(string m){throw new Exception();}public TextWriter OpenDebugLog(string p){throw new Exception();}}
class Tests{
 static long checks;static List<string> events=new List<string>();static void Yes(bool b,string m){checks++;if(!b)throw new Exception(m);}static void Text(List<string> target,int row,string text,int color){for(int i=0;i<text.Length&&i<40;i++){int ch=text[i];if(ch>=97&&ch<=122)ch-=32;target.Add("g:"+i+":"+row+":"+color+":"+(ch%64));}}
 static void Main(){GDVars.stingHpFlag=0;GameIo.Host=null;GDVars.gameFont=null;Por.Core.Debug.PrintHpDebug("disabled",0,255,128);Yes(events.Count==0,"flagzero no host/font required");GameIo.Host=new Host{Events=events};GDVars.stingArg=false;GDVars.gameFont=new Types.TFontArr();GDVars.video.ClearRect=(l,t,r,b)=>events.Add("c:"+l+":"+t+":"+r+":"+b);GDVars.video.DrawGlyph=(x,y,c,g)=>events.Add("g:"+x+":"+y+":"+c+":"+g);
  var rng=new Random(700391);for(int n=0;n<1800;n++){GDVars.stingHpFlag=(byte)(n%256);byte max=(byte)rng.Next(256),cur=(byte)rng.Next(256),drain=(byte)rng.Next(256);string msg=n%3==0?new string('a',55):n%3==1?"level drained":"";events.Clear();Por.Core.Debug.PrintHpDebug(msg,max,cur,drain);var want=new List<string>();if(GDVars.stingHpFlag!=0){want.Add("c:0:0:39:0");Text(want,0,max+" , "+cur+" , "+drain,14);Text(want,24,new string(' ',40),0);Text(want,24,msg,14);want.Add("key");want.Add("c:0:0:39:0");}Yes(events.SequenceEqual(want),"flag and exact HP/message/clear event trace "+n);}
  Console.WriteLine("Debug source-derived assertions: "+checks);
 }
}
